INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Nutze ich 2^n für die Subnetzanzahl?', 2, '[{"text": "Ja", "correct": true, "because": "n = geliehene Bits"}, {"text": "Nein", "correct": false, "because": "Korrekte Formel"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Hosts hat /26 nach der Formel?', 3, '[{"text": "62", "correct": true, "because": "2^(32-26) - 2 = 64 - 2"}, {"text": "64", "correct": false, "because": "Ohne Abzug"}, {"text": "60", "correct": false, "because": "Falsche Subtraktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) 2^(32-m) - 2 gibt nutzbare Hosts. b) 2^n ist für Subnetze.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "a) Hostformel, b) Subnetzformel"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei den Berechnungsgrundlagen?', 4, '[{"text": "Formeln", "correct": false, "because": "Kern der Berechnung"}, {"text": "Bitanzahl", "correct": false, "because": "Basis der Formeln"}, {"text": "Farbschema", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob 2^3 8 Subnetze ergibt?', 2, '[{"text": "Ja", "correct": true, "because": "2^3 = 8"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Subnetze entstehen bei /24 mit /27?', 3, '[{"text": "8", "correct": true, "because": "3 geliehene Bits, 2^3 = 8"}, {"text": "4", "correct": false, "because": "Für 2 Bits"}, {"text": "16", "correct": false, "because": "Für 4 Bits"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Formeln sind für Subnetting essenziell?', 5, '[{"text": "2^n", "correct": true, "because": "Subnetzanzahl"}, {"text": "2^(32-m) - 2", "correct": true, "because": "Nutzbare Hosts"}, {"text": "n^2", "correct": false, "because": "Falsche Formel"}, {"text": "m + 2", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) /28 hat 14 Hosts. b) 2^n zählt Hosts. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "2^n ist für Subnetze"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Berechnungsgrundlagen?', 4, '[{"text": "Bitanzahl", "correct": false, "because": "Definiert n und m"}, {"text": "Exponentiation", "correct": false, "because": "Kern der Formeln"}, {"text": "Betriebssystem", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat /30 2 nutzbare Hosts?', 2, '[{"text": "Ja", "correct": true, "because": "2^(32-30) - 2 = 2"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Hosts hat 255.255.255.240?', 4, '[{"text": "14", "correct": true, "because": "2^(32-28) - 2 = 16 - 2"}, {"text": "16", "correct": false, "because": "Ohne Abzug"}, {"text": "12", "correct": false, "because": "Falsche Subtraktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass 2^(32-m) die Subnetzanzahl gibt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Das ist für Hosts"}, {"text": "Ja", "correct": false, "because": "Falsche Zuordnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei den Berechnungen?', 3, '[{"text": "Korrekte Bitanzahl", "correct": true, "because": "Bestimmt n und m"}, {"text": "Schnelligkeit", "correct": false, "because": "Genauigkeit zählt"}, {"text": "Zufälligkeit", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) /16 hat 65.534 Hosts. b) 2^n ist für Hosts.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "2^n ist für Subnetze"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ergebnisse liefern die Formeln?', 5, '[{"text": "Subnetzanzahl", "correct": true, "because": "2^n"}, {"text": "Nutzbare Hosts", "correct": true, "because": "2^(32-m) - 2"}, {"text": "Netzwerkgeschwindigkeit", "correct": false, "because": "Irrelevant"}, {"text": "Protokollversion", "correct": false, "because": "Nicht berechnet"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei den Berechnungen unwichtig?', 3, '[{"text": "Exponentiation", "correct": false, "because": "Kern der Formeln"}, {"text": "Bitanzahl", "correct": false, "because": "Definiert Variablen"}, {"text": "Schriftgröße", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ergeben 4 geliehene Bits bei /24 16 Subnetze?', 3, '[{"text": "Ja", "correct": true, "because": "2^4 = 16"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob /31 nutzbare Hosts hat?', 2, '[{"text": "Nein", "correct": true, "because": "2^(32-31) - 2 = 0"}, {"text": "Ja", "correct": false, "because": "Keine nutzbaren Hosts"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie viele Subnetze hat 192.168.1.0/24 mit /28?', 4, '[{"text": "16", "correct": true, "because": "4 geliehene Bits, 2^4 = 16"}, {"text": "8", "correct": false, "because": "Für 3 Bits"}, {"text": "32", "correct": false, "because": "Für 5 Bits"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Formel nutze ich für nutzbare Hosts?', 3, '[{"text": "2^(32-m) - 2", "correct": true, "because": "Abzug für Netzwerk und Broadcast"}, {"text": "2^n", "correct": false, "because": "Für Subnetze"}, {"text": "m - 2", "correct": false, "because": "Falsche Formel"}]');
